CREATE TABLE IF NOT EXISTS schema_migrations(version text primary key, applied_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS users(id bigserial primary key, telegram_id text unique not null, name text, created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS products(id text primary key, slug text unique not null, type text not null check(type in ('template','ready_bot','module','service')), category text not null, title text not null, result text not null, description text, stack text, demo_url text, preview text, version text not null default '1.0.0', changelog text, status text not null default 'published' check(status in ('draft','published','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS license_plans(id text primary key, product_id text not null references products(id), name text not null, price_xtr integer not null check(price_xtr>0), projects integer not null default 1, commercial integer not null default 0, support_days integer not null default 0, updates_days integer not null default 0, terms text);
CREATE TABLE IF NOT EXISTS orders(id text primary key, user_id bigint not null references users(id), product_id text not null references products(id), license_id text not null references license_plans(id), product_title text, product_version text, license_name text, amount_xtr integer not null check(amount_xtr>0), currency text not null default 'XTR', status text not null check(status in ('pending','paid','fulfilled','expired','cancelled','delivery_failed','refund_pending','refunded')), invoice_link text, payload text unique not null, telegram_charge_id text unique, refund_reason text, created_at timestamptz not null default now(), paid_at timestamptz, fulfilled_at timestamptz, refunded_at timestamptz);
CREATE TABLE IF NOT EXISTS entitlements(id text primary key, user_id bigint not null references users(id), product_id text not null references products(id), license_id text not null references license_plans(id), order_id text unique not null references orders(id), active integer not null default 1, created_at timestamptz not null default now(), revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS product_assets(id text primary key, product_id text not null references products(id), version text not null, storage_key text not null, file_name text not null, mime_type text not null default 'application/zip', size_bytes bigint not null default 0, checksum_sha256 text, status text not null default 'pending' check(status in ('pending','scanning','approved','rejected','published','deleted')), scan_findings text, quarantine_key text, created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS delivery_events(id text primary key, entitlement_id text not null references entitlements(id), asset_id text references product_assets(id), token_hash text unique not null, expires_at bigint not null, used_at timestamptz, status text not null default 'issued', created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS analytics(id bigserial primary key, user_id bigint, event text, product_id text, meta text, created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS support_requests(id text primary key, user_id bigint, message text, status text default 'open', created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS admin_users(telegram_id text primary key, role text not null check(role in ('owner','editor','support')));
CREATE TABLE IF NOT EXISTS audit_log(id text primary key, actor_user_id bigint, action text not null, object_type text, object_id text, result text, meta text, created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS webhook_updates(update_id text primary key, processed_at timestamptz not null default now());
CREATE INDEX IF NOT EXISTS idx_orders_user_status ON orders(user_id,status);
CREATE INDEX IF NOT EXISTS idx_orders_payload ON orders(payload);
CREATE INDEX IF NOT EXISTS idx_entitlements_owner ON entitlements(user_id,active);
CREATE INDEX IF NOT EXISTS idx_assets_product_version ON product_assets(product_id,version,status);
